  throw new Error('Invalid NetScript database operation request.');
}
const task = /`db:/${operation}:/${Deno.args[1]}/`;
const command = new Deno.Command('deno', {
  args: ['task', task],
  env: request,
  stdin: 'inherit',
  stdout: 'inherit',
  stderr: 'inherit',
});
const status = await command.spawn().status;
Deno.exit(status.code);
`;

